class DelegationVerifier:
    def __init__(self, owner_public_key_raw:bytes):
        if len(owner_public_key_raw)!=32:raise AuthorizationDenied('invalid owner public key')
        self._key=owner_public_key_raw
        self._revoked:set[str]=set();self._redeemed:set[tuple[str,str]]=set();self._amendments:list[str]=[]
    def verify_signature(self,d:OwnerConditionalDelegation)->None:
        if d.owner_credential_scheme!='ED25519':raise AuthorizationDenied('unsupported owner credential scheme')
        try:verify_ed25519(self._key,canonical_json(d.unsigned_payload()),base64.b64decode(d.owner_signature,validate=True))
        except ValueError as exc:raise AuthorizationDenied('invalid owner signature') from exc
    def revoke(self,delegation_id:str,ctx:DaemonContext,owner_peer_uid:int)->None:
        if ctx.peer_uid!=owner_peer_uid:raise AuthorizationDenied('owner-only revocation')
        self._revoked.add(delegation_id)
    def redeem(self,d:OwnerConditionalDelegation,p:ChildProposal,preconditions_event:Mapping[str,Any],ctx:DaemonContext)->dict[str,Any]:
        self.verify_signature(d)
        if d.delegation_id in self._revoked or d.revocation_state!='ACTIVE':raise AuthorizationDenied('delegation revoked')
        if _utc(ctx.recorded_at)>=_utc(d.expires_at):raise AuthorizationDenied('delegation expired')
        if p.producer_session_id==d.owner_session_id:raise AuthorizationDenied('owner/producer session separation failed')
        if preconditions_event.get('to')!='PRECONDITIONS_PASS':raise AuthorizationDenied('PRECONDITIONS_PASS absent')
        if int(preconditions_event.get('ledger_sequence',-1))>=ctx.ledger_sequence:raise AuthorizationDenied('redemption must follow preconditions')
        if p.proposal_type not in d.allowed_child_authority_types or p.proposal_type not in CHILD_TYPES:raise AuthorizationDenied('child type outside delegation')
        exact=[(p.campaign,d.allowed_campaign),(p.family,d.allowed_family),(p.run_class in d.allowed_run_classes,True),(p.evidence_domain in d.allowed_evidence_domains,True),(p.scientific_root_hash in d.allowed_scientific_root_hashes,True),(p.dataset_manifest_hash,d.allowed_dataset_manifest_hash),(p.revision_hash,d.allowed_revision_hash),(p.pit_rule_hash,d.allowed_pit_rule_hash),(p.candidate_list_hash,d.allowed_candidate_list_hash),(p.candidate_grammar_hash,d.allowed_candidate_grammar_hash),(p.enumerator_hash,d.allowed_enumerator_hash),(p.evaluation_order_hash,d.allowed_evaluation_order_hash),(p.scientific_contract_hash,d.allowed_scientific_contract_hash),(p.evaluator_hash,d.allowed_evaluator_hash),(p.t1_prereg_hash,d.allowed_t1_prereg_hash),(p.integrity_void_contract_hash,d.allowed_integrity_void_contract_hash)]
        if not all(a==b for a,b in exact):raise AuthorizationDenied('DELEGATION_SCOPE_MATCH failed')
        if p.amendment_hash is not None and p.amendment_hash not in d.allowed_amendment_hashes:raise AuthorizationDenied('amendment hash outside delegation')
        predicates=(p.evaluator_registered,p.twenty_object_gate_pass,p.scientific_rule_changes==0,p.zero_llm,p.no_network,p.no_rng,p.float64,p.byte_identical_double_run,p.all_mandatory_goldens_pass,p.synthetic_benchmark_pass,p.pc7_evaluator_pass,p.research_memory_pass)
        if not all(predicates):raise AuthorizationDenied('frozen evaluator predicates failed')
        if not set(p.information_domains)<=set(d.allowed_information_domains):raise AuthorizationDenied('information-domain expansion')
        if set(p.requested_rights)&PROHIBITED or set(p.requested_rights)&set(d.explicit_prohibitions):raise AuthorizationDenied('prohibited right requested')
        key=(d.delegation_id,p.proposal_id)
        if key in self._redeemed:raise AuthorizationDenied('duplicate logical grant redemption')
        self._redeemed.add(key)
        sig_hash=hashlib.sha256(base64.b64decode(d.owner_signature)).hexdigest()
        event={'from':'PRECONDITIONS_PASS','to':'HUMAN_OWNER_SIGNED','authorization_mode':'PREAUTHORIZED_CONDITIONAL_DELEGATION','parent_delegation_id':d.delegation_id,'parent_owner_signature_hash':sig_hash,'child_proposal_id':p.proposal_id,'preconditions_event_id':preconditions_event['event_id'],'scope_hash':d.scope_hash,'redemption_event_id':'redeem-'+hashlib.sha256(canonical_json({'d':d.delegation_id,'p':p.proposal_id,'seq':ctx.ledger_sequence})).hexdigest()[:32],'daemon_recorded_at':ctx.recorded_at,'ledger_sequence':ctx.ledger_sequence,'immutable_session_id':ctx.session_id,'authorization_source':'HUMAN_OWNER_PREAUTHORIZED_CREDENTIAL','agent_signed':False}
        return event
    def register_amendment(self,amendment_id:str,amendment_hash:str,d:OwnerConditionalDelegation)->dict[str,Any]:
        expected=('C','A','B');idx=len(self._amendments)
        if idx>=3 or amendment_id!=expected[idx]:raise AuthorizationDenied('C->A->B order violation')
        if amendment_hash not in d.allowed_amendment_hashes:raise AuthorizationDenied('wrong amendment hash')
        self._amendments.append(amendment_id);return {'event_type':'AMENDMENT_REGISTERED','amendment_id':amendment_id,'ordinal':idx+1}

def wave1_continuation_allowed(t1_state:str)->bool:
    if t1_state=='TEST_VOIDED':return False
    if t1_state not in {'REPLICATION_SUPPORTED','REPLICATION_FAILED','EVIDENCE_INSUFFICIENT_CURRENT_COHORT'}:raise AuthorityError('unknown T1 state')
    return True

def require_complete_frozen_wave(candidate_count:int,completed:int,integrity_failure:bool)->None:
    if integrity_failure:raise AuthorityError('integrity failure stops wave')
    if candidate_count!=174 or completed!=174:raise AuthorityError('all 174 candidates required; no performance early stop')

"""P5 PC7 authority/amendment/trial runtime (engineering layer).

The daemon supplies ``peer_uid``, append-only sequence and canonical time.
Producer timestamps and payload role strings are never authorization inputs.
This module has no Research Memory write path; production persistence is the
separate, audited schema migration.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
import hashlib
import json
from typing import Any, Callable


STATES = ("PROPOSED", "PRECONDITIONS_PASS", "HUMAN_OWNER_SIGNED", "APPLIED")
RUN_CLASSES = {"STATISTICAL_TRIAL", "SYNTHETIC_TEST"}


class AuthorityError(RuntimeError):
    pass


class AuthorizationDenied(AuthorityError):
    pass


class BindingMismatch(AuthorityError):
    pass


def canonical_json(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True,
                      separators=(",", ":"), allow_nan=False).encode("utf-8")


def sha256(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def parse_utc(value: str) -> datetime:
    if not isinstance(value, str) or not value.endswith("Z"):
        raise AuthorityError("daemon time must be RFC3339 UTC")
    parsed = datetime.fromisoformat(value[:-1] + "+00:00")
    if parsed.utcoffset() != timezone.utc.utcoffset(parsed):
        raise AuthorityError("daemon time must be UTC")
    return parsed


@dataclass(frozen=True)
class FrozenBindings:
    family_id: str
    run_id: str
    run_class: str
    evidence_domain: str
    prereg_sha256: str
    dataset_manifest_sha256: str
    revision_lineage_sha256: str
    universe_rule_sha256: str
    validation_contract_sha256: str
    cost_contract: str
    evaluator_sha256: str
    cutoff: str
    wave_id: str | None = None
    candidate_grammar_sha256: str | None = None
    candidate_list_sha256: str | None = None
    candidate_count: int | None = None
    enumerator_sha256: str | None = None
    evaluation_order_sha256: str | None = None
    executable_contract_sha256: str | None = None
    risc_rule: str | None = None
    resource_scope: str | None = None

    def validate(self) -> "FrozenBindings":
        if self.run_class not in RUN_CLASSES:
            raise AuthorityError("unsupported run_class")
        for name, value in vars(self).items():
            if name.endswith("sha256") and value is not None:
                if len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
                    raise AuthorityError(f"invalid {name}")
        if self.wave_id is not None:
            required = (self.wave_id, self.candidate_grammar_sha256,
                        self.candidate_list_sha256, self.enumerator_sha256,
                        self.evaluation_order_sha256,
                        self.executable_contract_sha256, self.risc_rule,
                        self.resource_scope)
            if any(value is None for value in required) or self.candidate_count != 174:
                raise AuthorityError("Wave-1 bindings incomplete")
        return self

    @property
    def digest(self) -> str:
        self.validate()
        return sha256(canonical_json(vars(self)))


@dataclass(frozen=True)
class DaemonContext:
    peer_uid: int
    session_id: str
    recorded_at: str
    ledger_sequence: int

    def validate(self) -> "DaemonContext":
        if not isinstance(self.peer_uid, int) or self.peer_uid < 0:
            raise AuthorityError("invalid daemon peer uid")
        if not self.session_id or not isinstance(self.ledger_sequence, int):
            raise AuthorityError("daemon session/order missing")
        parse_utc(self.recorded_at)
        return self


@dataclass
class AuthorityProposal:
    proposal_id: str
    bindings: FrozenBindings
    producer_session_id: str
    expires_at: str
    state: str = "PROPOSED"
    events: list[dict[str, Any]] = field(default_factory=list)
    applied_grant_id: str | None = None


class AuthorityFSM:
    """Fail-closed FSM whose trust inputs come only from the daemon."""

    def __init__(self, owner_peer_uid: int,
                 daemon_context: Callable[[], DaemonContext]):
        self._owner_peer_uid = owner_peer_uid
        self._daemon_context = daemon_context

    def _ctx(self) -> DaemonContext:
        return self._daemon_context().validate()

    def _append(self, proposal: AuthorityProposal, target: str,
                details: dict[str, Any]) -> None:
        current_index = STATES.index(proposal.state)
        if current_index + 1 >= len(STATES) or STATES[current_index + 1] != target:
            raise AuthorityError(f"illegal transition {proposal.state}->{target}")
        ctx = self._ctx()
        if proposal.events and ctx.ledger_sequence <= proposal.events[-1]["ledger_sequence"]:
            raise AuthorityError("daemon ledger order is not append-only")
        proposal.events.append({
            "from": proposal.state, "to": target,
            "daemon_recorded_at": ctx.recorded_at,
            "ledger_sequence": ctx.ledger_sequence,
            "immutable_session_id": ctx.session_id,
            "peer_uid": ctx.peer_uid,
            "details": details,
        })
        proposal.state = target

    def preconditions_pass(self, proposal: AuthorityProposal,
                           observed_binding_digest: str) -> None:
        if observed_binding_digest != proposal.bindings.digest:
            raise BindingMismatch("precondition binding digest mismatch")
        self._append(proposal, "PRECONDITIONS_PASS",
                     {"binding_digest": observed_binding_digest})

    def human_owner_sign(self, proposal: AuthorityProposal) -> None:
        ctx = self._ctx()
        if ctx.peer_uid != self._owner_peer_uid:
            raise AuthorizationDenied("HUMAN_OWNER_SIGNED requires owner daemon credential")
        if ctx.session_id == proposal.producer_session_id:
            raise AuthorizationDenied("owner session must differ from producer session")
        self._append(proposal, "HUMAN_OWNER_SIGNED",
                     {"owner_peer_uid": ctx.peer_uid})

    def apply(self, proposal: AuthorityProposal) -> str:
        ctx = self._ctx()
        if ctx.peer_uid != self._owner_peer_uid:
            raise AuthorizationDenied("APPLIED requires owner daemon credential")
        if parse_utc(ctx.recorded_at) >= parse_utc(proposal.expires_at):
            raise AuthorizationDenied("grant expired under daemon-authoritative time")
        grant_id = "grant-" + sha256(canonical_json({
            "proposal_id": proposal.proposal_id,
            "binding_digest": proposal.bindings.digest,
            "owner_session": ctx.session_id,
        }))[:32]
        self._append(proposal, "APPLIED", {"grant_id": grant_id})
        proposal.applied_grant_id = grant_id
        return grant_id


@dataclass
class Attempt:
    attempt_id: str
    logical_trial_id: str
    ordinal: int
    state: str = "RUNNING"


class TrialRegistry:
    """One logical wave per grant; infrastructure retries keep its identity."""

    def __init__(self) -> None:
        self._logical_by_grant: dict[str, tuple[str, str]] = {}
        self._attempts: dict[str, list[Attempt]] = {}

    def open_wave(self, grant_id: str, candidate_list_sha256: str) -> Attempt:
        existing = self._logical_by_grant.get(grant_id)
        if existing is None:
            logical = "logical-" + sha256(canonical_json(
                {"grant_id": grant_id, "candidate_list_sha256": candidate_list_sha256}))[:32]
            self._logical_by_grant[grant_id] = (logical, candidate_list_sha256)
            self._attempts[logical] = []
        else:
            logical, frozen_hash = existing
            if frozen_hash != candidate_list_sha256:
                raise BindingMismatch("new candidate list requires a new grant/wave")
        ordinal = len(self._attempts[logical]) + 1
        attempt = Attempt(f"{logical}-attempt-{ordinal:04d}", logical, ordinal)
        self._attempts[logical].append(attempt)
        return attempt

    def void_attempt(self, attempt: Attempt) -> None:
        if attempt.state != "RUNNING":
            raise AuthorityError("only running attempt can be voided")
        attempt.state = "ATTEMPT_VOID"

    def complete(self, attempt: Attempt) -> None:
        if attempt.state != "RUNNING":
            raise AuthorityError("only running attempt can complete")
        if any(a.state == "COMPLETED" for a in self._attempts[attempt.logical_trial_id]):
            raise AuthorityError("duplicate logical result")
        attempt.state = "COMPLETED"

    @property
    def logical_trial_count(self) -> int:
        return len(self._logical_by_grant)
